window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[33]={"id":"033","numero":33,"titre":"Allaitement maternel","objectifs":[{"id":"33-1","rang":"A","rubrique":"Prise en charge","titre":"Connaître les bénéfices de l’allaitement maternel","contenu":"<p>Le <span class=\"kw-def\">lait maternel (LM)</span> est le <strong>lait le plus adapté</strong> à la croissance et au développement du nourrisson. Sa composition est <strong>variable</strong> (selon le <span class=\"kw-def\">stade</span> de lactation, le terme, l’âge, le nycthémère, voire le moment de la tétée), constamment ajustée aux besoins physiologiques. Il a <strong><span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>2</span> g</span>randes fonctions</strong> chez l’enfant : <span class=\"kw-clinique\">nutritive</span> et <span class=\"kw-clinique\">immunologique</span>.</p>\n\n      <h4>Composition du lait maternel</h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Éléments</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Éléments nutritifs</strong></td>\n            <td>\n              <ul>\n                <li>Eau, oligoéléments</li>\n                <li><span class=\"kw-bio\">Lactose</span>, protéines solubles (α-lactoglobulines)</li>\n                <li><span class=\"kw-bio\">AGE</span> (acide linoléique, α-linolénique), <span class=\"kw-bio\">triglycérides</span> à chaîne longue</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Éléments non nutritifs</strong><br><em>(rôle immunologique = immunité passive)</em></td>\n            <td>\n              <ul>\n                <li>Protéines essentielles : <span class=\"kw-bio\">lysozyme</span>, <span class=\"kw-bio\">immunoglobulines</span>, <span class=\"kw-bio\">lactoferrine</span></li>\n                <li>Éléments cellulaires : <span class=\"kw-bio\">lymphocytes</span>, <span class=\"kw-bio\">polynucléaires</span>, macrophages</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Teneur basse</strong> <em>(à supplémenter)</em></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Caséine</span> (protéine à digestion lente)</li>\n                <li><span class=\"kw-alerte\">Vitamine D</span>, <span class=\"kw-alerte\">Vitamine K</span>, <span class=\"kw-alerte\">Fer</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Alimentation maternelle</strong></td>\n            <td>Peu d’impact sur la composition du LM, <em>sauf</em> teneur en : graisses (AG polyinsaturés), iode, sélénium, vitamines A et B</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Variations dans les 1ers jours d’<span class=\"kw-ci\">allaitement</span></h4>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-def\">Stade</span></th><th>Caractéristiques</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Colostrum</strong><br><em>(1ers allaitements)</em></td>\n            <td>\n              <ul>\n                <li>Couleur <strong>orangée</strong></li>\n                <li><span class=\"kw-bio\">Pauvre en graisses</span></li>\n                <li>Riche en <span class=\"kw-bio\">IgA</span>, glycoprotéines, oligosaccharides, cellules immunitaires</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span class=\"kw-chiffre\">J15</span></strong></td>\n            <td>Lait de plus en plus <strong>riche en graisses</strong> <em>(rôle dans la maturation cérébrale et rétinienne)</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Comparaison lait maternel <em><span class=\"kw-bio\">vs</span></em> lait de vache</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Particularité du LM</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Protéines</strong></td>\n            <td>\n              <ul>\n                <li><strong>Plus pauvre en caséines</strong> (explique sa couleur translucide)</li>\n                <li>Plus riche en protéines non nutritives (lactoferrine, Ig, lysozyme) → mieux adapté à un nouveau-né au système immunitaire immature</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vitamine D</strong></td>\n            <td>Moins riche en <span class=\"kw-bio\">vitamine D</span> → source de <span class=\"kw-alerte\">rachitisme</span> (intérêt d’une <strong>supplémentation systématique</strong>)</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bénéfices chez la mère</h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Bénéfice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Cancer</strong></td>\n            <td>\n              <ul>\n                <li>Diminution du cancer de l’<span class=\"kw-clinique\">ovaire</span> : <span class=\"kw-chiffre\">−8 %</span> du risque épithélial dès <span class=\"kw-chiffre\">5 mois</span> d’AM</li>\n                <li>Diminution du cancer du <span class=\"kw-clinique\">sein</span> : <span class=\"kw-chiffre\">−4 %</span>/an d’AM, encore plus marqué si <strong>BRCA1</strong> (<span class=\"kw-chiffre\">−40 %</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Vasculaire</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Perte de poids</span> / diminution de la <span class=\"kw-clinique\">masse</span> grasse plus rapides en post-partum</li>\n                <li>Diminution de : <strong><span class=\"kw-etio\">obésité</span></strong>, <strong><span class=\"kw-def\">DT2</span></strong>, <strong>dyslipidémies</strong>, <strong><span class=\"kw-def\">HTA</span></strong>, <strong>maladie <span class=\"kw-bio\">CV</span></strong> <em>(bénéfice persistant après ménopause)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Psychique</strong></td>\n            <td>\n              <ul>\n                <li>Diminution de la fréquence de la <span class=\"kw-clinique\">dépression du post-partum</span></li>\n                <li>Diminue la réponse au stress, améliore le bien-être et l’estime de soi</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>\n              <ul>\n                <li>Favorise le <strong>lien mère/enfant</strong></li>\n                <li>Avantage financier (meilleure protection contre la dénutrition dans les pays en voie de développement)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Bénéfices chez l’enfant</h4>\n\n      <table >\n        <thead>\n          <tr><th>Domaine</th><th>Bénéfice</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Principal +++</strong></td>\n            <td><span class=\"kw-alerte\">Diminution des infections pédiatriques</span> : <strong>ORL</strong>, <strong>gastroentérite</strong>, <strong>respiratoire</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Pathologies réduites</strong></td>\n            <td>\n              <ul>\n                <li>Allergies : <strong><span class=\"kw-clinique\">eczéma</span></strong> chez le &lt;<span class=\"kw-chiffre\"> 2 ans</span>, <strong>rhinite <span class=\"kw-etio\">allergique</span></strong> chez le &lt;<span class=\"kw-chiffre\"> 5 ans</span>, <strong><span class=\"kw-def\">asthme</span></strong> entre <span class=\"kw-chiffre\">5–18 ans</span></li>\n                <li>Leucémies pédiatriques : <span class=\"kw-chiffre\">−20 %</span> dès <span class=\"kw-chiffre\">6 mois</span> d’AM</li>\n                <li>Risque de <strong>malocclusion dentaire</strong></li>\n                <li>Probable <span class=\"kw-ttt\">réduction</span> du risque d’<strong><span class=\"kw-etio\">obésité</span></strong> et de <strong><span class=\"kw-def\">diabète</span></strong></li>\n                <li><span class=\"kw-alerte\">Mort subite du nourrisson</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Intelligence</strong></td>\n            <td>Gain de QI <span class=\"kw-chiffre\">+3</span></td>\n          </tr>\n          <tr>\n            <td><strong>Spécifique du prématuré</strong></td>\n            <td>\n              <ul>\n                <li>Améliore la tolérance digestive et le développement cognitif</li>\n                <li>Réduit le risque d’<span class=\"kw-alerte\">ECUN</span> (entérocolite ulcéro-nécrosante)</li>\n                <li>Modalités possibles : sein, tasse, pipette, cuillère, SNG, ou <strong>lait de Lactarium</strong> <em>(centre de collecte de lait de donneuses bénévoles pour prématurés et nv-né de faible poids de naissance)</em></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Piège.</strong> Les <strong>modifications de l’aspect esthétique des seins</strong> sont plus liées <strong>à la <span class=\"kw-ci\">grossesse</span> elle-même</strong> qu’à l’<span class=\"kw-ci\">allaitement</span>. C’est un argument fréquemment opposé à l’AM qu’il faut savoir corriger.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent · 69 — Trouble psy <span class=\"kw-ci\">grossesse</span> - postpartum</em></p>","frequence":0},{"id":"33-2","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence, les facteurs influençant l’allaitement","contenu":"<h4><span class=\"kw-def\">Épidémiologie</span> — chiffres clés</h4>\n\n      <table >\n        <thead>\n          <tr><th>Donnée</th><th>Valeur</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Géographie</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-def\">Prévalence</span> et durée de l’AM en France sont <strong>parmi les plus faibles d’Europe</strong></li>\n                <li>Régions où la <span class=\"kw-def\">prévalence</span> est plus élevée : Île-de-France, Est, départements d’outre-mer</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Prévalence</span></strong></td>\n            <td>\n              <ul>\n                <li>En maternité : <span class=\"kw-chiffre\">70 %</span> (<span class=\"kw-chiffre\">60 %</span> exclusif,<span class=\"kw-chiffre\"> 10 %</span> partiel)</li>\n                <li>À <span class=\"kw-chiffre\">3 mois</span> : <span class=\"kw-chiffre\">40 %</span></li>\n                <li>À <span class=\"kw-chiffre\">6 mois</span> : <span class=\"kw-chiffre\">&lt; 20 %</span> <em>(ancien réf :<span class=\"kw-chiffre\"> 10 %</span> à<span class=\"kw-chiffre\"> 1 an</span>)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée</strong></td>\n            <td>\n              <ul>\n                <li>Durée médiane (ancien réf) : <span class=\"kw-chiffre\">15 semaines</span> (dont 24 j exclusifs)</li>\n                <li>Durée idéale recommandée : <span class=\"kw-chiffre\">4 à 6 mois</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs favorisant l’<span class=\"kw-ci\">allaitement</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Terrain</span></strong></td>\n            <td>\n              <ul>\n                <li>Femme âgée, diplômée, profession qualifiée, <strong>primipare</strong></li>\n                <li><strong>Soutien</strong> de l’entourage, prise de décision d’AM <strong>avant la <span class=\"kw-ci\">grossesse</span></strong></li>\n                <li>Accouchement dans une maternité labellisée <span class=\"kw-clinique\">IHAB</span> (Initiative Hôpital Ami des Bébés)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Promotion</strong></td>\n            <td>\n              <ul>\n                <li>Promotion de l’AM = objectif du <strong>Programme National Nutrition Santé (PNNS)</strong></li>\n                <li><strong>Code du travail</strong> : pauses sur le temps de travail, lieux appropriés pour exprimer le lait, horaires souples</li>\n                <li>Implication des <strong>pédiatres</strong> doit être exemplaire</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-def\">Facteurs de risque</span> d’arrêt prématuré <span class=\"kw-chiffre\">(5 catégories)</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li>Jeune, primipare, célibataire, faible statut socio-économique, mère récemment immigrée</li>\n                <li>Décision tardive d’allaiter, 1<sup>ère</sup> expérience d’<span class=\"kw-ci\">allaitement</span>, expérience passée négative</li>\n                <li><span class=\"kw-alerte\">Utilisation précoce d’une tétine</span>, <span class=\"kw-etio\">tabagisme</span>, <span class=\"kw-etio\">obésité</span>, exercice d’une profession</li>\n                <li>Manque de confiance, incertitude sur la quantité de lait prise, perception d’une insuffisance de lait</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bébé</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Perte de poids</span> <span class=\"kw-chiffre\">&gt; 10 %</span></li>\n                <li>Faible prise de poids</li>\n                <li>Problèmes de succion</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Entourage</strong></td>\n            <td>\n              <ul>\n                <li>Absence de soutien du partenaire</li>\n                <li>Perception négative du père</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Organisation en maternité</strong></td>\n            <td>\n              <ul>\n                <li>Mise au sein différée, 1<sup>er</sup> peau à peau retardé</li>\n                <li>Méconnaissance et manque de soutien des professionnels</li>\n                <li><span class=\"kw-ci\">Allaitement</span> à horaires fixes</li>\n                <li><span class=\"kw-alerte\">Recours aux compléments de lait artificiel en maternité</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Politiques</strong></td>\n            <td>Congé de maternité court et peu rémunéré</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":0},{"id":"33-3","rang":"A","rubrique":"Prise en charge","titre":"Savoir expliquer les modalité pratiques de l’allaitement maternel","contenu":"<h4>Conseils pour l’<span class=\"kw-ci\">allaitement</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Conseil</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>1<sup>ère</sup> tétée</strong></td>\n            <td>\n              <ul>\n                <li>Mise au sein <strong>immédiate</strong>, si possible en salle de travail</li>\n                <li>Délai : sans précipitation, mais <span class=\"kw-chiffre\">&lt; 30 min</span> après la naissance</li>\n                <li>Colostrum riche en Ig → favorise la <strong>montée laiteuse</strong> ; réflexe de succion à son maximum</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Installation</strong></td>\n            <td>\n              <ul>\n                <li>Mère assise ou couchée</li>\n                <li>Donner les 2 seins à chaque tétée <em>(alterner → diminue les complications)</em></li>\n                <li>Bouche du nouveau-né doit prendre <span class=\"kw-alerte\">largement l’aréole</span>, <span class=\"kw-alerte\">pas seulement le mamelon</span></li>\n                <li>Menton et nez contre le sein, tête légèrement inclinée en arrière</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Horaires</strong></td>\n            <td>\n              <span class=\"kw-ci\">Allaitement</span> <strong>souple à la demande</strong> (horaires libres) :\n              <ul>\n                <li>Fréquence moyenne : <span class=\"kw-chiffre\">1 tétée toutes les 2 à 3 h</span> au début, puis espacement progressif guidé par le nouveau-né</li>\n                <li>Repères pour décider : regard / comportement de l’enfant (mouvements des yeux, des lèvres, de la tête, main à la bouche)</li>\n                <li><span class=\"kw-alerte\">Ne pas attendre l’agitation ou les pleurs</span></li>\n                <li><span class=\"kw-alerte\">Ne pas juger seulement sur la courbe de poids</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Durée d’une tétée</strong></td>\n            <td>\n              Variable selon l’enfant :\n              <ul>\n                <li>Soit très courte (enfant très actif, tétée efficace sans s’arrêter)</li>\n                <li>Soit plus longue (nouveau-né, prématuré, enfant plus lent ou « tétouille » = succion non nutritive)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Signes d’un <span class=\"kw-ci\">allaitement</span> efficace</h4>\n\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Repère</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Tétées</strong></td><td><span class=\"kw-chiffre\">8–12 tétées/jour</span> efficaces, y compris la nuit pendant les 1<sup>ers</sup> mois (succion nutritive)</td></tr>\n          <tr><td><strong>Selles</strong></td><td><span class=\"kw-chiffre\">&gt; 3 selles/jour</span>, <strong>molles, grumeleuses, jaunes</strong>, durant les 1<sup>ers</sup> mois</td></tr>\n          <tr><td><strong>Urines</strong></td><td><span class=\"kw-chiffre\">5–6 couches mouillées et lourdes/jour</span> (témoin de diurèse satisfaisante)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>Conseils à encourager <em><span class=\"kw-bio\">vs</span></em> <span class=\"kw-ci\">à éviter</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Encourager ✅</th><th>Éviter ❌</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td>\n              <ul>\n                <li>Laisser l’enfant avec sa mère <strong><span class=\"kw-chiffre\">24h</span>/24</strong></li>\n                <li>Lavage quotidien des seins à l’eau et au savon</li>\n                <li>Protection des mamelons par compresse sèche (éviter la macération)</li>\n                <li>Encourager les associations de soutien à l’AM</li>\n                <li>Boissons abondantes, alimentation variée, riche en protéines et calcium</li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Proscription du <strong><span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">alcool</span>, excitants</strong> (café, thé)</li>\n                <li><span class=\"kw-alerte\">Aucune tétine artificielle ou sucette</span></li>\n                <li><span class=\"kw-alerte\">Pas de crèmes cosmétiques sur les seins</span> ; <em>pas besoin d’antisepsie</em></li>\n                <li>Aucun médicament ou régime visant à augmenter la sécrétion lactée</li>\n                <li>Production de lait diminue si l’on ajoute des biberons (moins de stimulation par l’enfant)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Couverture des besoins de l’enfant allaité</h4>\n\n      <table >\n        <thead>\n          <tr><th>Période</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Avant <span class=\"kw-chiffre\">6 mois</span></strong></td>\n            <td>\n              Le LM couvre seul tous les besoins du nourrisson de la naissance à<span class=\"kw-chiffre\"> 6 mois</span>, <strong>sauf</strong> :\n              <ul>\n                <li><span class=\"kw-ttt\">Vitamine D</span> : <span class=\"kw-chiffre\">800–1000 UI/j</span> (<span class=\"kw-chiffre\">400–800 UI</span>/j selon dernier réf de pédiatrie)</li>\n                <li><span class=\"kw-ttt\">Vitamine K</span> : <span class=\"kw-chiffre\">2 mg PO</span> à la <strong>naissance</strong>, <span class=\"kw-chiffre\">2 mg PO</span> entre <strong>J4–<span class=\"kw-chiffre\">J7</span></strong>, <span class=\"kw-chiffre\">2 mg PO</span> à <strong><span class=\"kw-chiffre\">1 mois</span></strong> si AM exclusif</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Après <span class=\"kw-chiffre\">6 mois</span></strong></td>\n            <td>\n              Supplémentation en <span class=\"kw-ttt\">fer</span> systématique chez les enfants encore exclusivement ou majoritairement allaités\n              <em>(dès <span class=\"kw-chiffre\">4 mois</span> chez le prématuré et le PAG si AM exclusif, selon nutrition)</em>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Conservation, transport et réchauffage du LM</h4>\n\n      <table >\n        <thead>\n          <tr><th>Condition</th><th>Durée / modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>T° ambiante (<span class=\"kw-chiffre\">20–25 °C</span>)</strong></td><td><span class=\"kw-chiffre\">4 h</span> maximum</td></tr>\n          <tr><td><strong>Réfrigérateur (<span class=\"kw-chiffre\">≤ 4 °C</span>)</strong></td><td><span class=\"kw-chiffre\">48 h</span> maximum, T° à vérifier régulièrement</td></tr>\n          <tr>\n            <td><strong>Congélateur (−<span class=\"kw-chiffre\">18 °C</span>)</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-chiffre\">4 mois</span> maximum</li>\n                <li>LM <strong>congelé d’emblée</strong> à son recueil, jamais après conservation au réfrigérateur</li>\n                <li>LM <strong>décongelé</strong> : consommer dans les <span class=\"kw-chiffre\">24 h</span>, <span class=\"kw-alerte\">jamais recongelé</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Transport</strong></td><td>Glacière ou sac isotherme avec pack de réfrigération</td></tr>\n          <tr>\n            <td><strong>Réchauffage</strong></td>\n            <td>\n              <ul>\n                <li><strong>Comment :</strong> bain-marie, chauffe-biberon, sous robinet d’eau chaude</li>\n                <li><span class=\"kw-alerte\">Pas de micro-ondes</span> (diminue la qualité nutritionnelle + risque élevé de brûlure)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Quand consommer ?</strong></td>\n            <td>\n              <ul>\n                <li>Si laissé à T° ambiante : <span class=\"kw-chiffre\">&lt; 1 h</span></li>\n                <li>Si réchauffé : <span class=\"kw-chiffre\">&lt; 30 min</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Inhibition de la lactation <em>(rang C)</em></h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Indications</strong></td>\n            <td>\n              <ul>\n                <li>Femme qui ne souhaite pas allaiter (souvent demandeuse)</li>\n                <li>Raisons médicales : <span class=\"kw-clinique\">fausses couches tardives, IMG, MFIU, décès néonatal</span>, accouchement <strong>sous X</strong></li>\n                <li><span class=\"kw-ci\">Contre-indication</span> médicale à l’AM : <span class=\"kw-alerte\">VIH-1, HTLV-1/2, tuberculose active non traitée</span>, <span class=\"kw-ttt\">chimiothérapie</span> anticancéreuse, traitement radioactif thérapeutique</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicamenteuse</strong></td>\n            <td>\n              <span class=\"kw-alerte\">Pas systématique</span> (effets vasoconstricteurs ; l’arrêt de lactation se fait spontanément en 15 j). Si indiqué, <strong>agonistes dopaminergiques</strong> :\n              <ul>\n                <li><span class=\"kw-ttt\">Lisuride</span> : <span class=\"kw-chiffre\">2 cp/j (0,2 mg)</span> pendant 14 j, à débuter dans les <span class=\"kw-chiffre\">24 h</span> post-accouchement, au cours des repas (tolérance digestive)</li>\n                <li><span class=\"kw-ttt\">Cabergoline</span> : <span class=\"kw-chiffre\">1 mg</span> en 1 prise unique dans les <span class=\"kw-chiffre\">24 h</span> du post-partum</li>\n                <li><span class=\"kw-ttt\">Quinagolide</span></li>\n                <li><span class=\"kw-ci\">Bromocriptine n’est plus indiquée</span> (risques <span class=\"kw-bio\">CV</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non médicamenteuse</strong></td>\n            <td><em>Pas d’argument scientifique</em> pour : acupuncture, homéopathie, physiothérapie, bandage des seins, brassières, glace…</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 31 — Accouchement - suites de couche normales · 32 — Evaluation du nouveau-né · 47 — <span class=\"kw-def\">Suivi</span> d'un nourrisson, d’un enfant, d'un adolescent</em></p>","frequence":2},{"id":"33-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les complications de l’allaitement","contenu":"<p>Les complications de l’AM se hiérarchisent en 4 entités : <strong>engorgement pathologique</strong>, <strong>crevasses du mamelon</strong>, <strong>mastite / lymphangite / galactophorite</strong>, <strong><span class=\"kw-clinique\">abcès</span> du sein lactant</strong>, auxquelles s’ajoute l’<strong>insuffisance de lait</strong>.</p>\n\n      <h4>Engorgement pathologique</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définition</strong></td>\n            <td>Stase de lait entraînant une <strong>augmentation de la pression intra-alvéolaire</strong> → empêche l’écoulement du lait et la tétée de qualité</td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              Sein <strong>gonflé, tendu, douloureux, brillant</strong>, avec <span class=\"kw-clinique\">œdème</span> voire rougeur diffuse :\n              <ul>\n                <li><span class=\"kw-clinique\">Tension douloureuse</span> : contemporaine de la montée de lait</li>\n                <li><span class=\"kw-clinique\">Œdème</span> : stase capillaire et lymphatique</li>\n                <li>Pathologique si : <span class=\"kw-alerte\">fièvre, douleur, gêne à l’écoulement du lait</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td><span class=\"kw-alerte\">Aucun examen indiqué</span> — diagnostic uniquement clinique</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong></td>\n            <td><strong>Congestion mammaire</strong> = « montée de lait » (2–3<sup>e</sup> jour du PP, installation physiologique de la lactation)</td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Tétées <strong>fréquentes et efficaces</strong>, sans limitation de leur nombre ou durée</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ol>\n                <li><strong>Extraction du lait</strong> : tétées fréquentes et efficaces, massage, tire-lait</li>\n                <li>Reprise des tétées efficaces (éviter récidive et <span class=\"kw-clinique\">évolution</span> vers mastite)</li>\n                <li><span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">antalgiques</span> pour diminuer <span class=\"kw-clinique\">œdème</span> et douleur</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non recommandé</strong></td>\n            <td>Restriction hydrique, bandage des seins (aggravent l’inconfort). Packs de glace ou topiques : efficacité non démontrée</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Crevasses du mamelon</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td><span class=\"kw-alerte\">Rupture</span> de la barrière cutanée du mamelon</td></tr>\n          <tr>\n            <td><strong>Cause</strong></td>\n            <td>\n              Friction anormale mamelon / bouche du bébé = cause principale, favorisée par :\n              <ul>\n                <li>Mauvaise prise du sein +++</li>\n                <li>Plus rarement : <strong>troubles de succion</strong> ou <strong>frein de langue trop court</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Clinique</strong> <em>(4 étapes)</em></td>\n            <td>\n              <ol>\n                <li>Mamelon <strong>douloureux</strong>, sans signes cutanés au départ (douleur parfois très intense)</li>\n                <li>Mamelon devient <strong>rouge et irrité</strong></li>\n                <li>Apparition de <strong>fissures / érosions</strong> cutanées sur l’extrémité du mamelon (= crevasses)</li>\n                <li><strong>Saignement</strong> possible (non grave, mais inquiétant pour la mère)</li>\n              </ol>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Risques</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Baisse de la lactation</span> : mauvaise stimulation du sein</li>\n                <li><span class=\"kw-alerte\">Mastite</span> : porte d’entrée infectieuse (<strong><span class=\"kw-etio\">staphylocoque</span></strong> ou <strong>candidose</strong>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Positionnement correct au sein + soutien adapté</td>\n          </tr>\n          <tr>\n            <td><strong>Prise en charge</strong></td>\n            <td>\n              <ul>\n                <li>Correction de la technique de succion (suffit dans la majorité des cas)</li>\n                <li>Topiques cicatrisants : application de <strong>colostrum</strong> ou de <strong>lait maternel</strong> en fin de tétée</li>\n                <li><span class=\"kw-ttt\">ATB PO</span> si surinfection cutanée (pour éviter la mastite)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Mastite / Lymphangite / Galactophorite</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Définitions</strong></td>\n            <td>\n              <ul>\n                <li><strong>Mastite</strong> : inflammation du sein avec ou sans infection</li>\n                <li><strong>Lymphangite</strong> : assimilable à la mastite <span class=\"kw-etio\">inflammatoire</span></li>\n                <li><strong>Galactophorite</strong> : considérée comme une mastite infectieuse</li>\n              </ul>\n            </td>\n          </tr>\n          <tr><td><strong>Cause</strong></td><td><span class=\"kw-clinique\">Stase du lait</span></td></tr>\n          <tr>\n            <td><strong>Délai</strong></td>\n            <td><span class=\"kw-chiffre\">≤ 3 mois</span> après la naissance, le plus souvent autour de la <strong>2<sup>e</sup> semaine du post-partum</strong></td>\n          </tr>\n          <tr>\n            <td><strong>Symptômes</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Syndrome grippal brutal</span></li>\n                <li><span class=\"kw-alerte\">Fièvre &gt; 38,5 °C</span> + <span class=\"kw-clinique\">frissons</span></li>\n                <li>Douleur dans <strong>1 sein</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Examen clinique</strong></td>\n            <td>\n              <ul>\n                <li>Zone <span class=\"kw-etio\">inflammatoire</span> : <strong>rouge, chaude, indurée</strong>, ± <span class=\"kw-clinique\">adénopathie</span> satellite</li>\n                <li>Formes sévères : <span class=\"kw-clinique\">cellulite avec « peau d’orange »</span></li>\n                <li>Clinique ne distingue pas mastite infectieuse <em><span class=\"kw-bio\">vs</span></em> non, <strong>mais</strong> : pus dans le lait = <span class=\"kw-clinique\">signe de Budin</span> → <strong>galactophorite</strong></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              Diagnostic clinique, examens <strong>inutiles</strong> en général :\n              <ul>\n                <li><strong><span class=\"kw-bio\">NFS</span> / <span class=\"kw-bio\">CRP</span></strong> : <span class=\"kw-def\">syndrome inflammatoire</span> avec hyperleucocytose (non spécifique)</li>\n                <li><strong>Prélèvement bactériologique de lait</strong> : recommandé</li>\n                <li><strong><span class=\"kw-imagerie\">Échographie</span> mammaire</strong> : si atypique, traînant, ou doute sur un <span class=\"kw-clinique\">abcès</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Microbiologie</strong></td>\n            <td>\n              <ul>\n                <li><strong>Prélèvement</strong> après toilette minutieuse du sein, sans prendre les 1<sup>ers</sup> mL extraits</li>\n                <li>Germes : <span class=\"kw-bio\">Staphylocoque doré</span> (le plus fréquent), <span class=\"kw-bio\">E. coli</span>, <span class=\"kw-bio\">Streptocoque B</span> (à envisager si <strong>mastite bilatérale</strong>)</li>\n                <li><strong>Interprétation</strong> : chez la femme en bonne santé, 10²–10⁵ germes dont <span class=\"kw-chiffre\">70 % de staph à coagulase −</span> ; en faveur d’une mastite infectieuse → <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> g</span>erme isolé <span class=\"kw-chiffre\">&gt; 10⁶/mL</span></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-clinique\">Abcès</span> du sein lactant</h4>\n\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Collection de pus <strong>bien délimitée</strong> dans le sein, <strong>complication de la mastite</strong></td></tr>\n          <tr><td><strong>Fréquence</strong></td><td><span class=\"kw-chiffre\">≈ 1 %</span> des femmes allaitant</td></tr>\n          <tr><td><strong>Délai</strong></td><td>Vers la <span class=\"kw-chiffre\">6<sup>e</sup> semaine</span> (mais peut survenir à tout moment de la lactation et au <span class=\"kw-ttt\">sevrage</span>)</td></tr>\n          <tr><td><strong>Début</strong></td><td>Souvent insidieux, douleurs chroniques, tableau à bas bruit</td></tr>\n          <tr>\n            <td><strong>Clinique</strong></td>\n            <td>\n              <ul>\n                <li>Signes inflammatoires sévères : douleur <strong>pulsatile / insomniante</strong>, rougeur, chaleur, <span class=\"kw-clinique\">œdème</span></li>\n                <li><span class=\"kw-clinique\">Abcès</span> <strong>froid</strong> sans inflammation : plus rare</li>\n                <li><span class=\"kw-clinique\">Masse fluctuante</span> avec changement de coloration cutanée <span class=\"kw-clinique\">rouge violacé</span> <em>(fait la différence avec la mastite)</em></li>\n                <li><span class=\"kw-alerte\">Nécrose cutanée possible</span></li>\n                <li><span class=\"kw-clinique\">Fièvre</span> <strong>plus modérée</strong> que dans la mastite, voire absente</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Paraclinique</strong></td>\n            <td>\n              <ul>\n                <li><strong><span class=\"kw-bio\">NFS</span> / <span class=\"kw-bio\">CRP</span></strong> : <span class=\"kw-def\">syndrome inflammatoire</span> avec hyperleucocytose, <span class=\"kw-bio\">CRP</span> élevée</li>\n                <li><strong><span class=\"kw-imagerie\">Échographie</span></strong> (radiologue compétent en sénologie) : si doute (spécifique)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>Éviter toute stase de lait ; agir vite en cas d’engorgement, de canal bouché, de mamelon douloureux</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Insuffisance de lait (IL)</h4>\n\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>IL primaire</strong><br><em>(exceptionnelle)</em></td>\n            <td>\n              Incapacité maternelle à produire du lait en quantité suffisante :\n              <ul>\n                <li>Origine <strong>hormonale</strong></li>\n                <li>Origine <strong>anatomique</strong> : <span class=\"kw-ttt\">chirurgie</span> esthétique (prothèse mammaire, plastie de <span class=\"kw-ttt\">réduction</span>)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>IL secondaire</strong><br><em>(principalement)</em></td>\n            <td>\n              <ol>\n                <li>Conduite inappropriée de l’AM (tétées inefficaces et/ou trop peu nombreuses)</li>\n                <li>Diminution du transfert de lait + de la sécrétion lactée (favorisée par la <strong>séparation mère/enfant</strong>)</li>\n              </ol>\n            </td>\n          </tr>\n          <tr><td><strong>Conséquence</strong></td><td><span class=\"kw-alerte\">Principale cause d’interruption précoce de l’AM</span></td></tr>\n          <tr>\n            <td><strong>Prévention</strong></td>\n            <td>\n              <em>Perception inappropriée d’IL = situation la plus fréquente</em>\n              <ul>\n                <li>Conseils / soutien pour restaurer la confiance maternelle</li>\n                <li>Mises au sein plus fréquentes pour stimuler la sécrétion lactée</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non efficace ❌</strong></td>\n            <td>Tire-lait, <span class=\"kw-ttt\">dompéridone</span>, <span class=\"kw-ttt\">métoclopramide</span>, oxytocine, galactologues à base de plantes : <span class=\"kw-alerte\">aucune preuve d’efficacité</span></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>Pièges chez l’enfant.</strong> L’<span class=\"kw-clinique\">ictère au lait maternel</span> est <strong>sans <span class=\"kw-alerte\"><span class=\"kw-def\">critère de</span> gravité</span></strong> → <span class=\"kw-alerte\">ne doit pas faire interrompre l’AM</span>. Les <strong>difficultés de succion</strong> (plus fréquentes chez l’immature) peuvent nécessiter l’utilisation temporaire d’un tire-lait.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 158 — <span class=\"kw-def\">Sepsis</span> et <span class=\"kw-def\">choc septique</span> · 32 — Evaluation du nouveau-né</em></p>","frequence":0},{"id":"33-5","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes et les facteurs favorisant les complications de l’allaitement","contenu":"<h4>Mécanismes des complications</h4>\n\n      <table >\n        <thead>\n          <tr><th>Complication</th><th>Mécanisme principal</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Engorgement pathologique</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Stase de lait</span> → ↑ pression intra-alvéolaire → blocage de l’écoulement du lait</li>\n                <li>Composante vasculaire associée : stase capillaire et lymphatique → <span class=\"kw-clinique\">œdème</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Crevasses du mamelon</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Friction anormale</span> mamelon / bouche du bébé = mécanisme central</li>\n                <li><span class=\"kw-clinique\">Évolution</span> : douleur → rougeur → fissure / <span class=\"kw-clinique\">érosion</span> → saignement possible</li>\n                <li>Porte d’entrée potentielle pour <strong>S. aureus</strong> ou <strong>candidose</strong> → mastite</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mastite / galactophorite</strong></td>\n            <td>\n              <ul>\n                <li>Mécanisme initial = <span class=\"kw-clinique\">stase du lait</span> (engorgement non drainé)</li>\n                <li>Colonisation <span class=\"kw-etio\">bactérienne</span> secondaire : <span class=\"kw-etio\">Staphylocoque</span> doré (le + fréquent), E. coli, Strepto B (si <strong>bilatérale</strong>)</li>\n                <li>Pus dans le lait = <strong>signe de Budin</strong> → galactophorite</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-clinique\">Abcès</span> du sein</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Évolution</span> d’une <span class=\"kw-clinique\">mastite non ou mal drainée</span> (suspendre l’AM expose à cette complication)</li>\n                <li>Constitution d’une collection purulente bien délimitée</li>\n                <li>Germes : <span class=\"kw-etio\">staphylocoque</span> doré, streptocoque A, entérocoque</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Insuffisance de lait</strong></td>\n            <td>\n              <ul>\n                <li>Primaire (rare) : hormonale ou anatomique (<span class=\"kw-ttt\">chirurgie</span> mammaire esthétique / <span class=\"kw-ttt\">réduction</span>)</li>\n                <li>Secondaire (++) : conduite inappropriée de l’AM, séparation mère/enfant → ↓ stimulation neurohormonale → ↓ prolactine / ocytocine → ↓ production</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Focus — causes d’engorgement <em>(détaillé)</em></h4>\n\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mauvaise technique d’<span class=\"kw-ci\">allaitement</span></strong></td>\n            <td>\n              <ul>\n                <li>Initiation retardée de l’AM à la naissance</li>\n                <li>Mauvaise prise du sein</li>\n                <li>Conséquences : extraction de lait inefficace, limitation arbitraire fréquence / durée des tétées, compléments, canal lactifère bouché</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Engorgement physiologique</strong></td>\n            <td><span class=\"kw-def\">Incidence</span> <span class=\"kw-chiffre\">−50 %</span> si les tétées se font à la demande de l’enfant</td>\n          </tr>\n          <tr>\n            <td><strong>Obstruction d’un canal lactifère</strong></td>\n            <td>\n              Bouchon de <strong>caséine, lipides, substances solidifiées par sels calciques</strong> :\n              <ul>\n                <li><strong>Clinique</strong> : petit bouton <span class=\"kw-clinique\">blanc, voire marron ou verdâtre</span> sur le mamelon, douloureux, engorgement du secteur du canal bouché</li>\n                <li><strong>CAT</strong> : positionner le menton du bébé sur la zone indurée pendant la tétée, éviter tout obstacle à l’écoulement (vêtements serrés), compresses chaudes humides, puis massages doux et retrait du bouchon si insuffisant</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Facteurs favorisant les complications</h4>\n\n      <table >\n        <thead>\n          <tr><th>Catégorie</th><th>Facteurs</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Pratique d’AM</strong></td>\n            <td>\n              <ul>\n                <li>Mise au sein différée</li>\n                <li>Mauvaise prise du sein, tétées limitées en fréquence ou durée</li>\n                <li>Compléments de lait artificiel en maternité</li>\n                <li><span class=\"kw-ttt\">Sevrage</span> trop rapide ou trop brutal</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li>Crevasses pré-existantes (porte d’entrée infectieuse)</li>\n                <li>Mauvaise hygiène / défaut de lavage des mains</li>\n                <li>Vêtements trop serrés (favorisent l’obstruction canalaire)</li>\n                <li>Antécédent de mastite (récidive si cause non corrigée)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Bébé</strong></td>\n            <td>\n              <ul>\n                <li>Troubles de succion (frein de langue trop court ++)</li>\n                <li>Prématurité, immaturité de la succion</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Anatomique</strong></td>\n            <td>\n              <ul>\n                <li>Anomalie d’un canal galactophore</li>\n                <li>Tumeur du sein sous-jacente (à évoquer si mastite récidivante toujours au même endroit)</li>\n                <li><span class=\"kw-ttt\">Chirurgie</span> mammaire antérieure (prothèse, plastie)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> <span class=\"kw-clinique\">Stase du lait + mauvaise technique d’AM = couple causal central</span> des 4 complications mammaires (engorgement → crevasses → mastite → <span class=\"kw-clinique\">abcès</span>). La prévention efficace est <strong>la même</strong> partout : <span class=\"kw-ttt\">drainage</span> du sein <strong>fréquent, efficace, sans restriction</strong>.\n      </div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 312 — Tumeur sein · 31 — Accouchement - suites de couche normales</em></p>","frequence":0},{"id":"33-6","rang":"B","rubrique":"Prise en charge","titre":"Allaitement et médicaments, infections et toxiques","contenu":"<h4>Toxiques et <span class=\"kw-ci\">allaitement</span> maternel</h4>\n\n      <table >\n        <thead>\n          <tr><th><span class=\"kw-etio\">Toxique</span></th><th>Effet</th><th>Mesures préventives</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Polluants</strong></td>\n            <td>Peuvent s’accumuler dans la chaîne alimentaire (mère → LM)</td>\n            <td><em>Bénéfices du LM surpassent les potentiels effets délétères</em></td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Tabac</span></strong></td>\n            <td><span class=\"kw-bio\">Nicotine / cotinine</span> passent dans le LM en quantités significatives</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-etio\">Tabac</span> <strong>déconseillé mais ne CI pas l’AM</strong></li>\n                <li>Encourager le <strong><span class=\"kw-ttt\">sevrage</span></strong></li>\n                <li>Délai <span class=\"kw-chiffre\">≥ 2 h</span> avant la mise au sein suivante (si <span class=\"kw-ttt\">sevrage</span> complet impossible)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-etio\">Alcool</span></strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-alerte\">Moindre production de lait</span></li>\n                <li><span class=\"kw-alerte\">Augmentation des arrêts précoces de l’AM</span></li>\n              </ul>\n            </td>\n            <td>\n              <ul>\n                <li>Éviter la consommation pendant l’AM</li>\n                <li>Délai <span class=\"kw-chiffre\">≥ 2 h</span> avant la mise au sein suivante (si consommation modérée et ponctuelle)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Drogues</strong></td>\n            <td>Passent dans le LM ; l’organisme immature de l’enfant peut y être sensible (somnolence excessive ou agitation)</td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Cocaïne</span> : CI selon nutrition ; <em>ne CI pas selon gynéco</em></li>\n                <li><span class=\"kw-clinique\">Cannabis</span> : <strong>déconseillé</strong> (THC liposoluble, présent dans LM)</li>\n                <li><span class=\"kw-clinique\">Méthadone</span> : <strong>possible</strong> (quantité très faible dans le LM, ≈<span class=\"kw-chiffre\"> 1 %</span>)</li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Médicaments et <span class=\"kw-ci\">allaitement</span> maternel</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Règles</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Côté de la mère</strong></td>\n            <td>\n              <ul>\n                <li>S’interroger sur la pertinence de la prescription</li>\n                <li>Éviter les médicaments d’efficacité non démontrée et l’automédication</li>\n                <li>Éviter au maximum les associations médicamenteuses</li>\n                <li>Alerter la mère sur les signes à surveiller chez le nouveau-né : <span class=\"kw-clinique\">diarrhée, ictère, hypotonie, somnolence, mauvaise courbe de poids</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Côté du nouveau-né</strong></td>\n            <td>\n              <ul>\n                <li>Tenir compte d’une <strong>prématurité</strong> (immaturité métabolique et rénale), d’une pathologie néonatale, d’une anomalie <span class=\"kw-etio\">génétique</span> (déficit en <span class=\"kw-bio\">G6PD</span>)</li>\n                <li>Vigilance accrue durant le <strong>1<sup>er</sup> mois</strong> de vie</li>\n                <li>Identifier les interactions avec les médicaments administrés au nouveau-né / nourrisson</li>\n                <li>Tenir compte du type d’<span class=\"kw-ci\">allaitement</span> (exclusif ou mixte)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Prise ponctuelle</strong></td>\n            <td>Généralement sans risque. Si médicament potentiellement dangereux : envisager une <strong>suspension provisoire</strong> de l’AM, reprise selon la demi-vie d’élimination</td>\n          </tr>\n          <tr>\n            <td><strong>Traitement prolongé</strong></td>\n            <td>\n              <ul>\n                <li>Utiliser un médicament avec données sur le passage dans le lait : si dose calculée reçue par l’enfant <span class=\"kw-chiffre\">&lt; 1 %</span> de la dose maternelle rapportée au poids → AM généralement possible</li>\n                <li>Identifier les risques selon profil de toxicité et marge thérapeutique</li>\n                <li>Préférer un médicament utilisé en pédiatrie : si dose ingérée estimée <span class=\"kw-chiffre\">&lt; 10 %</span> de la dose pédiatrique recommandée → AM généralement possible</li>\n                <li>À défaut de donnée : choisir un médicament à <strong>faible biodisponibilité</strong> (voie topique, inhalée), <strong>forte liaison aux protéines</strong>, <strong>demi-vie courte</strong>, sans métabolites actifs ; <span class=\"kw-ci\">éviter les médicaments très lipophiles</span></li>\n                <li><span class=\"kw-ci\">Éviter les formes retard / à libération prolongée</span></li>\n                <li>Pour les médicaments à demi-vie courte : prendre <strong>juste après une tétée</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-ci\">Contre-indications</span> infectieuses</h4>\n\n      <table >\n        <thead>\n          <tr><th>Statut</th><th>Pathologies / modalités</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>AM <span class=\"kw-ci\">contre-indiqué</span></strong></td>\n            <td>\n              Risque de transmission par le LM prouvé :\n              <ul>\n                <li><span class=\"kw-ci\">VIH</span> dans les pays développés (bénéficiant de laits artificiels)</li>\n                <li><span class=\"kw-ci\">HTLV 1/2</span> <em>(la <strong>congélation</strong> permet de détruire le virus)</em></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Suspension temporaire</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-clinique\">Tuberculose pulmonaire active</span> : isoler la mère du nouveau-né le temps de la contagion (<span class=\"kw-chiffre\">≥ 2 semaines</span> de traitement)</li>\n                <li><span class=\"kw-clinique\">Varicelle maternelle</span> en fin de <span class=\"kw-ci\">grossesse</span> : isoler la mère, <strong>extraire le lait pour le donner</strong> à l’enfant (contamination par contact)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non — pas de CI</strong></td>\n            <td>\n              <ul>\n                <li><strong>Zona, <span class=\"kw-etio\">HSV</span></strong> : contamination par contact direct. <em>Si <span class=\"kw-clinique\">lésion</span> sur le sein</em> → extraire le lait pour le donner, ou allaiter avec l’autre sein</li>\n                <li><strong><span class=\"kw-etio\">CMV</span></strong> : passage dans le lait prouvé mais <span class=\"kw-chiffre\">sans risque</span>. <em>Sauf grand prématuré</em> : congeler le lait, voire pasteuriser</li>\n                <li><strong><span class=\"kw-etio\">VHB</span></strong> : contamination lactée possible mais <strong>enfant protégé par la sérovaccination</strong> mise en place à la naissance</li>\n                <li><strong><span class=\"kw-etio\">VHC</span></strong> : retrouvé dans le lait, contamination par voie lactée <strong>non prouvée</strong></li>\n              </ul>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4><span class=\"kw-ci\">Contre-indications</span> iatrogènes</h4>\n\n      <table >\n        <thead>\n          <tr><th>Volet</th><th>Détails</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Sources d’information</strong></td>\n            <td>\n              <ul>\n                <li>Site du <strong>CRAT</strong> (Centre de renseignements sur les agents tératogènes)</li>\n                <li>Centres régionaux de pharmacovigilance des CHU</li>\n                <li>Site <strong>Lactmed</strong>, Association des Lactariums de France</li>\n                <li><span class=\"kw-alerte\">Les informations du Vidal ne sont pas pertinentes pour l’AM</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Médicaments CI</strong></td>\n            <td>\n              <span class=\"kw-ci\">Amiodarone</span>, <span class=\"kw-ci\">antimitotiques</span>, <span class=\"kw-ci\">aspirine à dose anti-inflammatoire</span>, <span class=\"kw-ci\">fluindione</span>, <span class=\"kw-ci\">lithium</span> (liste non exhaustive)\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Autres CI</strong></td>\n            <td>\n              <ul>\n                <li>Traitement par <span class=\"kw-ci\">iode 131</span></li>\n                <li>Xénobiotiques non évalués (phytothérapie « sauvage »)</li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Non — pas de CI</strong></td>\n            <td><span class=\"kw-chiffre\">Aucun examen d’imagerie ne justifie d’interrompre l’AM</span> (hors médecine nucléaire) — <em>accord professionnel</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <h4>Autres <span class=\"kw-ci\">contre-indications</span></h4>\n\n      <table >\n        <thead>\n          <tr><th>Origine</th><th>Pathologies</th></tr>\n        </thead>\n        <tbody>\n          <tr>\n            <td><strong>Mère</strong></td>\n            <td>\n              <ul>\n                <li><span class=\"kw-ci\">Psychose</span></li>\n                <li><span class=\"kw-ci\">Cardiopathie sévère</span></li>\n                <li><span class=\"kw-ci\">Néphropathie sévère</span></li>\n              </ul>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Enfant</strong></td>\n            <td><span class=\"kw-ci\">Galactosémie congénitale</span> <em>(maladie <span class=\"kw-etio\">génétique</span> rare = défaut d’utilisation du galactose)</em></td>\n          </tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 169 — <span class=\"kw-etio\">VIH</span> · 159 — <span class=\"kw-def\">Tuberculose</span> Enfant / Adulte · 168 — Herpesvirus · 144 — Deuil · 36 — Contraception</em></p>","frequence":1}],"astuces":[],"strategie":{"redflags":"<ul><li><span class=\"kw-alerte\">Fièvre &gt; 38,5 °C</span> + <span class=\"kw-clinique\">syndrome grippal brutal</span> + douleur dans un sein → <span class=\"kw-def\">mastite</span></li><li><span class=\"kw-alerte\">Masse fluctuante</span> avec peau <span class=\"kw-clinique\">rouge violacée</span> → <span class=\"kw-def\">abcès du sein lactant</span> (complication de la mastite)</li><li><span class=\"kw-clinique\">Signe de Budin</span> (pus dans le lait) → <span class=\"kw-def\">galactophorite</span> (mastite infectieuse)</li><li><span class=\"kw-alerte\">Mastite récidivante toujours au même endroit</span> → éliminer une <span class=\"kw-etio\">tumeur du sein</span></li></ul>","principes":"<p>Chaque complication a sa propre ligne de conduite — du plus simple (correction de technique) au plus invasif (<span class=\"kw-ttt\">drainage</span> chirurgical). Le <strong>drainage du sein</strong> est le fil conducteur commun : <span class=\"kw-ci\">suspendre l'allaitement expose au développement d'un abcès</span>.</p><p><strong>Engorgement pathologique</strong></p><p><span class=\"kw-ci\">Restriction hydrique et bandage des seins déconseillés</span> (aggravent l'inconfort)</p><ul><li>Extraction du lait : <span class=\"kw-ttt\">tétées fréquentes et efficaces</span> ou <span class=\"kw-ttt\">tire-lait</span> ou <span class=\"kw-ttt\">massage</span></li><li><span class=\"kw-ttt\">AINS</span> ou <span class=\"kw-ttt\">antalgiques</span> pour réduire l'<span class=\"kw-clinique\">œdème</span> et la douleur</li></ul><p><strong>Crevasses des mamelons</strong></p><p>Meilleure prévention = <span class=\"kw-ttt\">positionnement correct au sein</span> dès le départ</p><ul><li>Correction de la <span class=\"kw-clinique\">technique de succion</span> : suffit dans la majorité des cas</li><li>Topiques cicatrisants : <span class=\"kw-ttt\">colostrum</span> ou <span class=\"kw-ttt\">lait maternel</span> appliqué sur le mamelon en fin de tétée</li><li><span class=\"kw-ttt\">ATB per os</span> si <span class=\"kw-etio\">surinfection cutanée</span> (pour prévenir la mastite)</li></ul><p><strong>Mastite <span class=\"q\">— lymphangite / galactophorite</span></strong></p><p><span class=\"kw-ci\">Suspension de l'allaitement expose à l'abcès</span> — poursuivre le <span class=\"kw-ttt\">drainage</span> même si le lait contient du pus (tire-lait + jeter le lait jusqu'à guérison)</p><ul><li><span class=\"kw-ttt\">Drainage du sein</span> efficace en priorité (tétées sans restriction, extraction manuelle ou tire-lait)</li><li><span class=\"kw-ttt\">Pénicilline M</span> (<span class=\"kw-chiffre\">5–7 jours</span>) si mastite infectieuse confirmée, symptômes graves d'emblée ou n'améliorant pas en <span class=\"kw-chiffre\">12–24h</span>, ou <span class=\"kw-clinique\">lésion</span> du mamelon visible</li><li><span class=\"kw-ttt\">Paracétamol</span> ± <span class=\"kw-ttt\">AINS</span> à visée <span class=\"kw-ttt\">antalgique</span></li></ul><p><strong><span class=\"kw-clinique\">Abcès</span> du sein lactant</strong></p><p>Prélèvements bactériologiques pour identification et <span class=\"kw-bio\">antibiogramme</span> (germes fréquents : <span class=\"kw-etio\">staphylocoque doré</span>, <span class=\"kw-etio\">streptocoque A</span>, <span class=\"kw-etio\">entérocoque</span>)</p><ul><li>Formes simples (<span class=\"kw-chiffre\">&lt; 3 cm</span>, homogènes) : <span class=\"kw-ttt\">ponctions itératives à l'aiguille</span> (alternative au <span class=\"kw-ttt\">drainage</span> chirurgical)</li><li>Formes non simples : <span class=\"kw-ttt\">incision et drainage chirurgical sous AG</span></li><li><span class=\"kw-ttt\">Drainage par tire-lait</span> du sein affecté — <span class=\"kw-ci\">allaitement</span> poursuivi du sein controlatéral</li></ul>","suivi":"<p><strong>Mastite :</strong> <span class=\"kw-def\">surveillance</span> rigoureuse pour dépister une <span class=\"kw-alerte\">évolution en abcès</span> (absence d'amélioration sous traitement = indication d'<span class=\"kw-imagerie\">échographie mammaire</span>).<br><strong>Mastite récurrente :</strong> rechercher mastite mal traitée initialement, persistance d'une mauvaise technique d'<span class=\"kw-ci\">allaitement</span>, infection cutanée associée, ou <span class=\"kw-alerte\">cause entraînant un faible drainage</span> (anomalie d'un canal, <span class=\"kw-etio\">tumeur</span>).<br><strong><span class=\"kw-clinique\">Abcès</span> :</strong> <span class=\"kw-imagerie\">échographie mammaire</span> par radiologue compétent en sénologie si doute diagnostique.</p>"},"cards":[]};